import { useCallback, useMemo } from 'react';

import { useIntl } from 'react-intl';

import {
  ActionList,
  Button,
  Icon,
  IconButton,
  SizableText,
  Stack,
  useMedia,
} from '@onekeyhq/components';
import type { IActionListItemProps } from '@onekeyhq/components';
import { useInviteCodeList } from '@onekeyhq/kit/src/views/ReferFriends/pages/InviteReward/components/InvitationDetailsSection/hooks/useInviteCodeList';
import { NATIVE_MEDIUM_ICON_HIT_SLOP } from '@onekeyhq/kit/src/views/ReferFriends/utils/touchTarget';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import type { EExportTimeRange } from '@onekeyhq/shared/src/referralCode/type';

import { ReferFriendsTestIDs } from '../testIDs';

export interface IFilterState {
  timeRange: EExportTimeRange;
  inviteCode?: string;
  startTime?: number;
  endTime?: number;
}

interface IFilterButtonProps {
  filterState: IFilterState;
  onFilterChange: (updates: Partial<IFilterState>) => void;
}

// Marks an active invite-code filter on both layouts. A solid funnel read
// as a pressed or broken button, so the icon stays outlined and gains a dot,
// like a badge, in the trigger's top-right corner.
function FilterActiveDot() {
  return (
    <Stack
      testID={ReferFriendsTestIDs.filterActiveDot}
      position="absolute"
      top={-1}
      right={-1}
      w="$2.5"
      h="$2.5"
      borderRadius="$full"
      borderWidth={2}
      borderColor="$bgApp"
      bg="$iconSuccess"
      pointerEvents="none"
    />
  );
}

export function FilterButton({
  filterState,
  onFilterChange,
}: IFilterButtonProps) {
  const intl = useIntl();
  const { codeListData } = useInviteCodeList();
  const { gtMd } = useMedia();

  const inviteCodeOptions = useMemo(() => {
    const options: Array<{
      label: string;
      value?: string;
      description?: string;
    }> = [
      {
        label: intl.formatMessage({
          id: ETranslations.referral_filter_code_all,
        }),
        value: undefined,
      },
    ];

    if (codeListData?.items) {
      codeListData.items.forEach((item) => {
        const note = item.note?.trim();
        options.push({
          label: item.code,
          value: item.code,
          description: note || undefined,
        });
      });
    }

    return options;
  }, [intl, codeListData]);

  const handleInviteCodeSelect = useCallback(
    (value?: string) => {
      onFilterChange({ inviteCode: value });
    },
    [onFilterChange],
  );

  const sections = useMemo(
    () => [
      {
        title: intl.formatMessage({
          id: ETranslations.referral_code_list,
        }),
        items: inviteCodeOptions.map((option) => ({
          label: option.label,
          description: option.description,
          descriptionNumberOfLines: 1,
          extra:
            filterState.inviteCode === option.value ? (
              <Icon name="CheckRadioSolid" size="$5" color="$icon" />
            ) : undefined,
          onPress: () => handleInviteCodeSelect(option.value),
        })) as IActionListItemProps[],
      },
    ],
    [intl, inviteCodeOptions, filterState, handleInviteCodeSelect],
  );

  // Check if any filters are active (not default values)
  const hasActiveFilters = useMemo(
    () => filterState.inviteCode !== undefined,
    [filterState.inviteCode],
  );

  // Fit mode sizes the sheet to the invite-code list. Percent 70 left a tall
  // empty frame whose unbounded ScrollView caused scroll jitter.
  const handleMobileClick = useCallback(() => {
    ActionList.show({
      title: intl.formatMessage({ id: ETranslations.referral_filter }),
      sections,
      sheetProps: {
        snapPointsMode: 'fit',
      },
    });
  }, [intl, sections]);

  // Desktop: Use component-style ActionList with Button trigger
  if (gtMd) {
    return (
      <ActionList
        title={intl.formatMessage({ id: ETranslations.referral_filter })}
        renderTrigger={
          <Button
            testID={ReferFriendsTestIDs.filterBtn}
            size="small"
            icon="Filter1Outline"
            childrenAsText={false}
          >
            <SizableText size="$bodyMdMedium">
              {intl.formatMessage({ id: ETranslations.referral_filter })}
            </SizableText>
            {hasActiveFilters ? <FilterActiveDot /> : null}
          </Button>
        }
        sections={sections}
        floatingPanelProps={{
          width: '$56',
          maxHeight: '$96',
        }}
      />
    );
  }

  // Mobile: Use ActionList.show() to avoid Portal nesting issues
  return (
    <Stack position="relative">
      <IconButton
        testID={ReferFriendsTestIDs.filterBtn}
        icon="Filter1Outline"
        variant="tertiary"
        hitSlop={NATIVE_MEDIUM_ICON_HIT_SLOP}
        title={intl.formatMessage({ id: ETranslations.referral_filter })}
        onPress={handleMobileClick}
      />
      {hasActiveFilters ? <FilterActiveDot /> : null}
    </Stack>
  );
}
